   128          ccic->bytes_per_element = (curc->pixel_type == EXR_PIXEL_HALF) ? 2 : 4;
   129          ccic->data_type         = (uint16_t) (curc->pixel_type);
   130      }
   131
   132      return EXR_ERR_SUCCESS;
