   657  static uint64_t
   658  compute_chunk_unpack_size (
   659      int                              y,
   660      int                              width,
   661      int                              height,
   662      int                              lpc,
   663      const struct _internal_exr_part* part)
   664  {
   665      uint64_t unpacksize = 0;
   666      if (part->chan_has_line_sampling || height != lpc)
   667      {
   668          const exr_attr_chlist_t* chanlist = part->channels->chlist;
   669          for (int c = 0; c < chanlist->num_channels; ++c)
   670          {
   671              const exr_attr_chlist_entry_t* curc = (chanlist->entries + c);
   672              uint64_t chansz = ((curc->pixel_type == EXR_PIXEL_HALF) ? 2 : 4);
   673              chansz *= ((uint64_t) width);
   674              if (curc->x_sampling > 1) chansz /= ((uint64_t) curc->x_sampling);
   675              chansz *= ((uint64_t) height);
   676              if (curc->y_sampling > 1)
   677              {
   678                  if (height > 1)
   679                  {
   680                      if (curc->y_sampling > height)
   681                          chansz /= ((uint64_t) height);
   682                      else
   683                          chansz /= ((uint64_t) curc->y_sampling);
   684                  }
   685                  else if ((y % ((int) curc->y_sampling)) != 0)
   686                      chansz = 0;
   687              }
   688              unpacksize += chansz;
   689          }
   690      }
   691      else
   692          unpacksize = part->unpacked_size_per_chunk;
   693      return unpacksize;
   694  }
